export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',plus:'M12 4v16M4 12h16',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 1 0 8 4 4 0 0 1 0-8M20 8v6m-3-3h6',threads:'M18 9c0-5-12-5-12 2 0 9 14 9 14 1 0-6-12-6-12-1 0 4 8 3 8-2V6',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',refresh:'M20 7A9 9 0 1 0 21 17M21 2v6h-6',copy:'M9 8h12v13H9zM15 8V3H3v13h6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',play:'m9 6 9 6-9 6z',back:'M20 12H4m6-6-6 6 6 6'};
export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`;
export const btn=(label,attrs='',kind='secondary',ic='')=>`<button class="button ${kind}" ${attrs}>${ic?icon(ic):''}${label}</button>`;
export const date=v=>v?new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Bishkek'}).format(new Date(v)):'';
export const number=v=>new Intl.NumberFormat('ru-RU').format(v||0);
export const formLink=username=>'https://t.me/'+(username||'sneg_ugc_bot')+'?start=c_sneg-october';
export const directions=a=>a.directions.map(d=>`<span class="pill">${d==='ugc'?'UGC':'Охваты'}</span>`).join('');
export function workLink(url,i=0){return url.includes('example.com')?`<button class="work-link" data-demo-work>${icon('play')}Пример ролика · демо${icon('external')}</button>`:`<a class="work-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('play')}Смотреть работу ${i+1}${icon('external')}</a>`;}
